fTrue:	[		^ nil.	]	ifFalse:	[		^ self class newQuotient firstTerm: self secondTerm: arg	].! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:56'!abs	"Answer an expression equivalent to the absolute value of the receiver"	^ self squared sqrt! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:59'!negated	"Answer an expression equivalent to the negation of the receiver"	"alternate:		^ self * -1.	"	^ (self class newConstant: 0) - self! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:46'!raisedTo: arg	"Answer the exponential expression of the receiver and arg"	^ self class newExponential firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:59'!reciprocal	"Answer an expression equivalent to the reciprocal of the receiver"	"alternate:		^ self raisedTo: -1.	"	^ (self class newConstant: 1) / self! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 19:13'!sqrt	"Answer my square root"	^ self raisedTo: 0.5! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:58'!squared	"Answer myself squared"	"alternate:   	^ self * self "^ self raisedTo: 2.! !!Expression methodsFor: 'as yet unclassified' stamp: 'jmi 5/15/2000 14:05'!variables	"Answer a Set of all the variables I contain"	^ self addVariablesTo: Set new.! !!Expression methodsFor: 'converting' stamp: 'jmi 5/15/2000 17:45'!asExpression	"Answer myself, since I'm already an Expression"	^ self! !!Expression methodsFor: 'converting' stamp: 'jmi 4/25/2000 12:35'!printSqueak	"Answer a string representation of my expression that can be evaluated by 'Compiler evaluate:' "	^ self subclassResponsibility! !!Expression methodsFor: 'converting' stamp: 'jmi 4/25/2000 12:34'!printString	"Answer a string representation of my expression"	^ self subclassResponsibility! !!Expression methodsFor: 'evaluation' stamp: 'jmi 7/1/2000 13:26'!at: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	^ self subclassResponsibility.! !!Expression methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:10'!evaluate	"a Variable Expression should never be sent this message, but if it does, return an error condition"		"Only constantExpressions will correctly evaluate.  variable expressions will return nil."	^ self at: nil.! !!Expression methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:12'!partialAt: anAssociation	"Evaluate my expression using the value association.	It takes a little longer than evaluateAt:, but can be useful	when optimizing functions of multiple variables"	^ self subclassResponsibility.! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:28'!cos	"Answer the cosine of the receiver"	^ self class newCos term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!cot	"Answer the cotangent of the receiver"	^ (self class newTan term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!csc	"Answer the cosecant of the receiver"	^ (self class newSin term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 18:57'!ln	"Answer the natural logarithm of the receiver"	^ self class newNaturalLog term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!sec	"Answer the secant of the receiver"	^ (self class newCos term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:28'!sin	"Answer the sine of the receiver"	^ self class newSin term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:35'!tan	"Answer the tangent of the receiver"	^ self class newTan term: self! !!Expression methodsFor: 'operation' stamp: 'jmi 5/15/2000 22:23'!operation	"Answer the symbol for the operation I represent"	^ self subclassResponsibility! !!Expression methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:16'!operationString	"Answer the string for the operation I represent	This only needs to be overidden by classes in which the commonly used symbol differs from the one Squeak uses.  for example, the carrat ^ is usually used for exponentialization, but in squeak it's used for returning values.  Therefore, operation needs to return #raisedTo: and operationString returns '^' "	^ self operation asString! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 16:53'!reduceConstantSubexpressions	"Answer myself with any  with constant suxexpressions evaluated."		"Default action is to do nothing"	^ self! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 5/16/2000 16:28'!simplify	"Answer a simplified expression"	^ self		reduceConstantSubexpressions		simplifyExpression! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 4/23/2000 20:50'!simplifyExpression	"Allow my instances to attempt to reduce themselves on instance creation.	For example, the addition expression could override reduceExpression to ckeck for its identity	and return an equivalent, reduced equation.	1+0 would be reduced to 1"		"Default action is to do nothing"	^ self! !!Expression methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 10:50'!derivative	"Answer my (partial) derivitive.  Can someone verify this is correct?"				"The variables typically come out backwards from the way I like them,				 so I reversed the array.  No real reason other than that."		^ self privateDerivative: self variables asArray reversed.! !!Expression methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:10'!derivative: aSymbolOrString	"Answer the my derivitive (partial or whatever) with respect to aSymbolOrString"	^ self protectedDerivative: aSymbolOrString asSymbol! !!Expression methodsFor: 'symbolic-private' stamp: 'jmi 5/18/2000 11:09'!privateDerivative: array	"Answer my (partial) derivitive, with respect to the array of variables.  Can someone verify this is correct?"	| derivative |		"Initialize derivative to zero, since the derivative of a constant expression is always zero"	derivative _ self class newConstant: 0.		"Take the sum of the partial derivatives"	array do:	[:variable |		derivative _ derivative + (self derivative: variable).	].		"Answer the derivative"	^ derivative! !!Expression methodsFor: 'symbolic-private' stamp: 'jmi 5/20/2000 14:50'!protectedDerivative: aSymbol	"Answer the my derivitive (partial or whatever) with respect to aSymbol"	"This is what you add to a new operation,	 and this is the method you call to calculate derivatives	 of your subexpressions from WITHIN instance methods"	^ self subclassResponsibility! !!Expression methodsFor: 'testing' stamp: 'jmi 7/1/2000 11:13'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"The subclasses override this to do a tree comparison rather than printString."	^ self printString = arg printString! !!Expression class methodsFor: 'class initialization' stamp: 'jmi 5/16/2000 15:18'!initialize	"Expression initialize"	Zero _ self newConstant: 0.	One _ self newConstant: 1.! !!Expression class methodsFor: 'documentation' stamp: 'jmi 5/18/2000 11:33'!addingANewOperation	"Instructions on how to add a new operation""ADDING A NEW OPERATIONNote: this may be outdated, as I have made modifications since writing this commentAdding a new operation does not always require creating a class for it.	For example, squared is not a special form of the exponential operation, it's just a shorthand for raisedTo: 2		It doesn't need its own class, since doing so would only make maintenance harder			(needing to modify squared and exponential in parallel).		An exponential expression has already been written, so that can be used to create an equivalent expression:				squared				self raisedTo: 2	Another example is negated, it doesn't make sense to have a separate class just for it... but now I'm seeing how it might be useful.	Another example is abs, even though d( abs( x raisedTo: n ) )/dx = n * abs( x raisedTo: n ) / x				I think the integral isn't as trivial...Steps to add another operation:	say you want to add the operations #foo and #bar:	General guidelines for writing a new expression		o  never access the instance variable directly, always use:				self term for unary operations				self firstTerm or self secondTerm for binary operations		o  once an instance has been created, NEVER alter it		o  this means it's perfectly fine to add simplification code into the initialize methods, just return self or a new simplified instance					(see 'simplify' method and the methods called from 'simplify')				(additional note: be careful with infinite recursion.  Remember simplify is called every instance creation...)		o  ...	Required Steps to add a unary ExpressionFoo		o  make the class ExpressionFoo with the superclass ExpressionUnary		o  add fooClass and newFoo class methods to Expression		o  add a #foo instance method to Expression				foo				^ self class newFoo term: self		o  add the method ExpressionFoo operation and have it return #foo		o  add the method ExpressionFoo protectedDerivative: and have it return the derivative			(look at other unary expression derivatives to see examples)		o  edit Expression class orderOfOperationsMatrix and add 'foo' to the order of operations		o  congratulations, you now have foo!!	Required Steps to add a binary ExpressionBar		o  make the class ExpressionBar with the superclass ExpressionBinary		o  add barClass and newBar class methods to Expression		o  add a #bar: instance method to Expression				bar: arg				^ self class newBar firstTerm: self secondTerm: arg		o  add the method ExpressionBar operation and have it return #bar:		o  add the method ExpressionBar protectedDerivative: and have it return the derivative			(look at other binary expression derivatives to see examples)		o  edit Expression class orderOfOperationsMatrix and add 'bar:' to the order of operations		o  congratulations, you now have bar:!!	Optional Steps to improve your operation		o  add a method ExpressionFoo simplifyExpression or ExpressionBar simplifyExpression			(see other classes for examples)"! !!Expression class methodsFor: 'documentation' stamp: 'jmi 5/20/2000 21:37'!examples	"Examples of use""To just use Expression, you will never need to know the names of any of the subclasses, or how to use the subclasses.  The Expression instance creation method knows about all of its subclasses (hard coded, but easily modifiable), and builds an expression tree	To instantiate an Expression, use one of the following:		Expression newFromString: 'x^7'		'x^7' asExpressionEXAMPLES:	(use alt+p to see the results for yourself)	'(1+32*x-7/x)' asExpression at: ({ #x->7 } as: Dictionary)		224	'(1+32*x-7/x)' asExpression at: 7		224	'(1 + 32*x - 7/y + cos(ln(tan((z^75*14/w)^0.5))))' asExpression at: ({ #x->7. #y->42. #z->4. #w->0.1212121 } as: Dictionary)		225.8333333333333	'(1 + 32*x - 7/y + cos(ln(tan((z^75*14/w)^0.5))))' asExpression at: 42.73		1369.196180669319	'(1+32*x-7/x)' asExpression derivative: #x		(32-(-7/(x^2)))	'sin(x)^2' asExpression derivative		((2*sin(x))*cos(x))	'sin(x)^2' asExpression derivative at: 3.14159265359		4.13646222309494e-13	'((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))' asExpression derivative		(((0-(0-((0-(7*(2*x)))/((x^2)^2))))*cos(((1+(32*x))-(7/x))))+((32-(0-(7/(x^2))))*((32-(-7/(x^2)))*(0-sin(((1+(32*x))-(7/x)))))))	'((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))' asExpression derivative derivative		((((0-(0-(((-14*((x^2)^2))-((0-(7*(2*x)))*((2*(x^2))*(2*x))))/(((x^2)^2)^2))))*cos(((1+(32*x))-(7/x))))+((0-(0-((0-(7*(2*x)))/((x^2)^2))))*((32-(-7/(x^2)))*(0-sin(((1+(32*x))-(7/x)))))))+(((0-(0-((0-(7*(2*x)))/((x^2)^2))))*((32-(-7/(x^2)))*(0-sin(((1+(32*x))-(7/x))))))+((32-(0-(7/(x^2))))*(((0-((0-(-7*(2*x)))/((x^2)^2)))*(0-sin(((1+(32*x))-(7/x)))))+((32-(-7/(x^2)))*(0-((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))))))))	'((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))' asExpression derivative derivative derivative		(((((0-(0-(((((... you get the point	'((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))' asExpression derivative derivative derivative at: 17		-933834.681033454			'This example shows how Expression could be used to convert standard equations to squeak format (see Compiler evaluate:)'.	'((32-(-7/(x^2)))*cos(((1+(32*x))-(7/x))))' asExpression printSqueak		'((32 - (0 - (7 / (x raisedTo: 2)))) * ((1 + (32 * x)) - (7 / x)) cos)'			A little more useful use of this would be to take the symbolic derivative of an equation,			and then convert the derivative to squeak for speed."! !!Expression class methodsFor: 'documentation' stamp: 'jmi 7/1/2000 12:59'!notes	"Things that are planned, or just notes to myself""It seems to go faster with simplification ENABLED.  It's in firstTerm:secondTerm: and term:I'm not sure exactly why this is since I thought I was using expressions that couldn't be simplified...Division by zero, and the like, should be intercepted rather than pinkboxing.Actually, I don't know if it actually pinkboxes.		Integration (later)		true equivalence (or at least allow things like x+y = y+x)		want to recognize - as negated if a symbol preceeds it... (not necessary)I want to be able to copy an expression without trying to simplify it.However, I tried running the code without simplifying, and didn't notice a speed increase, so this may not be a problem.ISSUESEquivalence is not yet fully implemented		This means the following code will evaluate to true:			('1' asExpression) = ('1' asExpression)		but this code will evaluate to false:			('x+y' asExpression) = ('y+x' asExpression)	Currently, if you evaluate an expression without specifying a value for every variable, it will return nil and look like an error occured.  This is intended.  The function is 'undefined'	I'm not sure, but negated may be placed in the wrong place at times.	I don't remember why I thought this..."! !!Expression class methodsFor: 'instance creation' stamp: 'jmi 4/24/2000 17:45'!newFromString: aString	"Answer an instance of me with the value aString"	| tokens |		"If it's all digits or periods, it's a literal constant"	(aString detect: [:c | c isDigit ifTrue: [ false ] ifFalse: [ c ~= $. ] ] ifNone: [ nil ]) = nil	ifTrue:	[		^ self newConstant: aString.	].		"All letters means it's a variable name"	"aString isAllLetters"	(aString detect: [:c | c isLetter not] ifNone: [nil]) = nil	ifTrue:	[		^ self newVariable: aString.	].		"If aString is neither a number, nor a valid variable name,		aString must have multiple parts, so tokenize it."	tokens _ self tokenize: aString.		"3 indicates a binary operation (firstExpression, operator, secondExpression)"	tokens size = 3	ifTrue:	[		^ (Expression newFromString: (tokens at: 1))				perform:	(tokens at: 2) asSymbol				with:		(Expression newFromString: (tokens at: 3))	].		"2 indicates a unary operation (operator, expression)"	tokens size = 2	ifTrue:	[		^ (Expression newFromString: (tokens at: 2)) perform: (tokens at: 1) asSymbol	].			"1 indicates a parenthesized operation."	tokens size = 1	ifTrue:	[		^ Expression newFromString: (tokens at: 1).	].	"Anything else means I couldn't parse an expression from the string"^ nil.! !!Expression class methodsFor: 'order of operations' stamp: 'jmi 4/26/2000 12:57'!orderOfOperationsMatrix	"Answer a matrix of the order of operations.	The higher in the table an operation is, the higher its precedence.	Operations on the same row have the same precedence"	"if two operations with the same precedence have the same exact characters except one has more at the beginning		(ie: 'sin' and 'arcsin')	then the larger one will NEVER actually be matched.	The Solution:		Give the longer one higher precedence	This may not be the best solution, but it seems to work in any case I can think of"	^ #(			#( 'arcSin' 'arcCos' 'arcTan' )			#( 'ln' 'sin' 'cos' 'tan' )			#( '^' )			#( '*' '/' )			#( '+' '-' )		)! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/24/2000 17:46'!newConstant: aStringOrNumber	"Answer a new instance of the constant expression"	^ self constantClass new value: aStringOrNumber asNumber! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newCos	"Answer a new instance of the cosine expression"	^ self cosineClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:10'!newDifference	"Answer a new instance of the subtraction expression"	^ self differenceClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:45'!newExponential	"Answer a new instance of the exponential expression"	^ self exponentialClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 18:56'!newNaturalLog	"Answer a new instance of the natural logarithm expression"	^ self naturalLogarithmClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:11'!newProduct	"Answer a new instance of the multiplication expression"	^ self productClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:11'!newQuotient	"Answer a new instance of the division expression"	^ self quotientClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newSin	"Answer a new instance of the sine expression"	^ self sineClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:08'!newSum	"Answer a new instance of the addition expression"	^ self sumClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newTan	"Answer a new instance of the cosine expression"	^ self tangentClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/24/2000 17:46'!newVariable: aStringOrSymbol	"Answer a new instance of the variable expression"	^ self variableClass new value: aStringOrSymbol asSymbol! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:17'!constantClass	"Answer the subclass used for constants"	^ ExpressionConstant! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:36'!cosineClass	"Answer the class used for cosine"	^ ExpressionCos! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:04'!differenceClass	"Answer the subclass used for subtraction"	^ ExpressionSubtraction! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:07'!exponentialClass	"Answer the subclass used for power"	^ ExpressionExponential! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 18:55'!naturalLogarithmClass	"Answer the class used for natual logarithms"	^ ExpressionLn! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:04'!productClass	"Answer the subclass used for multiplication"	^ ExpressionMultiplication! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:05'!quotientClass	"Answer the subclass used for division"	^ ExpressionDivision! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:36'!sineClass	"Answer the class used for sine"	^ ExpressionSin! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:03'!sumClass	"Answer the class used for addition"	^ ExpressionAddition! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:35'!tangentClass	"Answer the class used for tangent"	^ ExpressionTan! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:17'!variableClass	"Answer the subclass used for variables"	^ ExpressionVariable! !!Expression class methodsFor: 'private-tokenization' stamp: 'jmi 4/23/2000 20:10'!lastUnparenthesized: tokenMatrix in: expression	"Answer the position of the last unparenthesized operator, lowest in the order of operations, in expression"	| level substring safeToRemoveParenthesis wentHigh wentBackLow |	level _ 0.	"safeToRemoveParenthesis _ ((expression at: 1) = $() and: [(expression at: expression size) = $)]."	safeToRemoveParenthesis _ (expression beginsWith: '(') & (expression endsWith: ')').	wentHigh _ wentBackLow  _ false.tokenMatrix reverseDo:[:tokens |	expression size to: 1 by: -1 do:	[:position |		(expression at: position) = $)		ifTrue: [ level _ level + 1.  wentHigh _ true ]		ifFalse:		[			(expression at: position) = $(			ifTrue: [ level _ level - 1 ]			ifFalse:			[				level = 0				ifTrue:				[					wentHigh					ifTrue: [ wentBackLow _ true ].					substring _ expression copyFrom: position to: expression size.					tokens do:					[:token |						(substring beginsWith: token) ifTrue: [ ^ { position. substring copyFrom: 1 to: token size } ].					].				].			].		].		(level > 0) & wentBackLow		ifTrue: [ safeToRemoveParenthesis _ false ].		(level > 0) ifTrue: [ wentHigh _ true ].	].].safeToRemoveParenthesisifTrue:[	^ { 1. '(' }]ifFalse:[	"Not found"	^ { 0. '' }].! !!Expression class methodsFor: 'private-tokenization' stamp: 'jmi 4/23/2000 20:07'!tokenize: aString	"Answer an ordered collection of 1, 2, or 3 elements"	| expression tokens position operator |		"Remove whitespace"	expression _ aString withBlanksCondensed copyReplaceAll: ' ' with: ''.		"Convert any multicharacter exponential operation selectors to a single character"	expression _ expression copyReplaceAll: '**' with: '^'.	expression _ expression copyReplaceAll: 'raisedTo:' with: '^'.				"I need a way to search for all the operations calling the searcher only once.					The simplest solution would be to just assign a single character token for each					multicharacter operator"		"Find the position of the first unparenthesized binary operation"	tokens _ self lastUnparenthesized: self orderOfOperationsMatrix in: expression.		"Unpack the data answered"	position _ tokens at: 1.	operator _ tokens at: 2.	tokens _ nil.		"If position is zero, it means the expression cannot be parsed"	(position = 0)	ifTrue:	[			"Don't generate an error, simply return an empty OrderedCollection"		^ #()		"self error: 'expression cannot be parsed'."	]	ifFalse:	[			"Answer the expression with outer parens removed"		(operator = '(')		ifTrue:		[			^ { expression copyFrom: (operator size + 1) to: (expression size - 1) } as: OrderedCollection		].			"If the operator is not the first or last character, it's a binary operation"		((position > 1) and: [ position < expression size ])		ifTrue:		[				"Split the string into 3 parts (ie: tokenize the binary expression)"			tokens _ {						expression copyFrom: 1 to: (position - 1).						expression copyFrom: position to: (position + operator size - 1).						expression copyFrom: (position + operator size) to: expression size					} as: OrderedCollection.				"Convert the power operation back to something understood by Squeak"			tokens replaceAll: '^' with: 'raisedTo:'.		]		ifFalse:	"Otherwise the operation is unary (need to check for a postfix operation, and determine ordering)"		[				"Split the string into 2 parts (ie: tokenize the unary operation)"			tokens _ {						expression copyFrom: 1 to: operator size.						expression copyFrom: (operator size + 1) to: expression size					} as: OrderedCollection.				"Convert negated operator to a message squeak understands"			tokens replaceAll: '-' with: 'negated'.			tokens replaceAll: '+' with: 'abs'.		].			"Answer the tokenized form"		^ tokens	].! !!ExpressionBinary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:34'!firstTerm	"Answer my first term"	^ firstTerm! !!ExpressionBinary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:35'!secondTerm	"Answer my second term"	^ secondTerm! !!ExpressionBinary methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:24'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ self firstTerm addVariablesTo: (self secondTerm addVariablesTo: aSet)! !!ExpressionBinary methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:12'!at: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first second |	(		(first _ self firstTerm at: aDictionaryOrNumber) notNil	and:		[(second _ self secondTerm at: aDictionaryOrNumber) notNil]	)	ifTrue:	[		^ (first perform: self operation with: second)	]	ifFalse:	[		^ nil	]! !!ExpressionBinary methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:16'!partialAt: anAssociation	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first second |	(		(first _ self firstTerm partialAt: anAssociation) notNil	and:		[(second _ self secondTerm partialAt: anAssociation) notNil]	)	ifTrue:	[		^ (first perform: self operation with: second)	]	ifFalse:	[		^ nil	]! !!ExpressionBinary methodsFor: 'printing' stamp: 'jmi 4/26/2000 10:58'!printSqueak	"Answer a string representation of myself"	^ '(', self firstTerm printSqueak, ' ', self operation printString, ' ', self secondTerm printSqueak, ')'! !!ExpressionBinary methodsFor: 'printing' stamp: 'jmi 4/23/2000 17:30'!printString	"Answer a string representation of myself"	^ '(', self firstTerm printString, self operationString, self secondTerm printString, ')'! !!ExpressionBinary methodsFor: 'private-initialization' stamp: 'jmi 5/20/2000 21:38'!firstTerm: firstExpression secondTerm: secondExpression	"Learn both of my terms"	^ self firstTerm: firstExpression secondTerm: secondExpression simplify: true.! !!ExpressionBinary methodsFor: 'private-initialization' stamp: 'jmi 5/20/2000 14:21'!firstTerm: firstExpression secondTerm: secondExpression simplify: aBoolean	"Learn both of my terms"	firstTerm _ firstExpression.		"Allow the second expression to be a literal instead of just an expression"	secondExpression isNumber	ifTrue:	[		secondTerm _ self class newConstant: secondExpression.	]	ifFalse:	[		secondTerm _ secondExpression.	].	aBoolean	ifTrue:	[		^ self simplify.	].	^ self.! !!ExpressionBinary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:18'!reduceConstantSubexpressions	"collapse any constant subexpressions"	self isConstantExpression	ifTrue:	[		"Reduce to a single constant"		^ self class newConstant: self evaluate	]	ifFalse:	[		^ self	]! !!ExpressionBinary methodsFor: 'testing' stamp: 'jmi 7/1/2000 11:22'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	^	(self operation == arg operation)	and:		[			(self firstTerm = arg firstTerm)		and:			[self secondTerm = arg secondTerm]		].! !!ExpressionBinary methodsFor: 'testing' stamp: 'jmi 4/23/2000 17:28'!isConstantExpression	"Answer true if I only contain constants,	 answer false if I contain variables"	^ self firstTerm isConstantExpression and: [ self secondTerm isConstantExpression ]! !!ExpressionAddition methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:31'!operation	"Answer the symbol for the operation I represent"	^ #+! !!ExpressionAddition methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:34'!simplifyExpression	"Answer myself or a simpler version of myself"	self firstTerm = Zero	ifTrue:	[		^ self secondTerm	].	self secondTerm = Zero	ifTrue:	[		^ self firstTerm	].		"Cannot simplify"	^ self! !!ExpressionAddition methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:11'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self firstTerm protectedDerivative: aSymbol) + 		(self secondTerm protectedDerivative: aSymbol)! !!ExpressionExponential methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!base	"Answer my first term"	^ self firstTerm! !!ExpressionExponential methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:38'!exponent	"Answer my second term"	^ self secondTerm! !!ExpressionExponential methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operation	"Answer the symbol for the operation I represent"	^ #raisedTo:! !!ExpressionExponential methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operationString	"Answer the string representation for the operation I represent"	^ '^'! !!ExpressionExponential methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:37'!simplifyExpression	"Answer myself or a simpler version of myself"	(		(self base = One)	or:		[	self exponent = Zero	]	)	ifTrue:	"0 raisedTo: 0 should error, but this will return 1 instead (should be fixed later)"	[		^ self class newConstant: 1	].	self base = Zero	ifTrue:	[		^ self class newConstant: 0	].	self exponent = One	ifTrue:	[		^ self base	].		"Cannot simplify"	^ self! !!ExpressionExponential methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:13'!protectedDerivative: aSymbol	"Answer my derivative (this one's gonna take a while... do ln first)"	self exponent isConstantExpression	ifTrue:	[		self base isConstantExpression		ifTrue:			"constant raisedTo: constant"		[		"The derivative of a constant is zero"			^ self class newConstant: 0		]		ifFalse:			"variable raisedTo: constant"		[			^ (self exponent) *				(self base raisedTo: (self exponent - 1)) *				(self base protectedDerivative: aSymbol)		]	]	ifFalse:	[		self base isConstantExpression		ifTrue:			"constant raisedTo: variable"		[			^ (self base ln) *				(self) *				(self exponent protectedDerivative: aSymbol)		]		ifFalse:			"variable raisedTo: variable"		[					"^ self class newFromString: '(ln(x)+1)*x^x'"			^ self * ((self exponent * self base ln) protectedDerivative: aSymbol)		]	].! !!ExpressionMultiplication methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:33'!operation	"Answer the symbol for the operation I represent"	^ #*! !!ExpressionMultiplication methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:39'!simplifyExpression	"Answer myself or a simpler version of myself"	(		(self firstTerm = Zero)	or:		[	self secondTerm = Zero	]	)	ifTrue:	[		^ self class newConstant: 0	].	self firstTerm = One	ifTrue:	[		^ self secondTerm	].	self secondTerm = One	ifTrue:	[		^ self firstTerm	].		"I'm sure this is bad design... multiply shouldn't know how divide works.			I think it should be ok for divide to know how multiply works, since it's			a subclass, but I don't see how that could help in this situation""	theSecond = ('(1/', theFirst, ')')	ifTrue:	[		^ self class newConstant: 1	]."		"Cannot simplify"	^ self! !!ExpressionMultiplication methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:13'!protectedDerivative: aSymbol	"Answer my derivative"	^ ((self firstTerm protectedDerivative: aSymbol) * (self secondTerm)) +	  ((self firstTerm) * (self secondTerm protectedDerivative: aSymbol))! !!ExpressionDivision methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!denominator	"Answer my second term"	^ self secondTerm! !!ExpressionDivision methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!numerator	"Answer my first term"	^ self firstTerm! !!ExpressionDivision methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operation	"Answer the symbol for the operation I represent"	^ #/! !!ExpressionDivision methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:36'!simplifyExpression	"Answer myself or a simpler version of myself"	self numerator = Zero	ifTrue:	[		^ self class newConstant: 0	].	self denominator = One	ifTrue:	[		^ self numerator	].		"Another example of bad poking around in another object.  It doesn't alter anything, so is this ok?"	(		(self class == self denominator class)	and:		[ self denominator numerator = One ]	)	ifTrue:	[		" x / ( 1 / y ) == x * y "  "I think I could fix this by 'simplifying'		1/x		to	x raisedTo: -1"		^ self numerator * self denominator denominator	].		"Cannot simplify"	^ self! !!ExpressionDivision methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:12'!protectedDerivative: aSymbol	"Answer my derivative"	^ (((self firstTerm protectedDerivative: aSymbol) * (self secondTerm)) -		((self firstTerm) * (self secondTerm protectedDerivative: aSymbol))) /								(self secondTerm squared)! !!ExpressionSubtraction methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:33'!operation	"Answer the symbol for the operation I represent"	^ #-! !!ExpressionSubtraction methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:40'!simplifyExpression	"Answer myself or a simpler version of myself"	"If I check on the first term, it will produce an infinite loop,  negated does 0 - term.... begins with zero..."	self secondTerm = Zero	ifTrue:	[		^ self firstTerm	].		"Cannot simplify"	^ self! !!ExpressionSubtraction methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:14'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self firstTerm protectedDerivative: aSymbol) -			(self secondTerm protectedDerivative: aSymbol)! !!ExpressionUnary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 18:26'!term	"Answer my term"	^ term! !!ExpressionUnary methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:26'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ self term addVariablesTo: aSet! !!ExpressionUnary methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:13'!at: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first |	(first _ self term at: aDictionaryOrNumber) notNil	ifTrue:	[		^ (first perform: self operation)	]	ifFalse:	[		^ nil	]! !!ExpressionUnary methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:17'!partialAt: anAssociation	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first |	(first _ self term partialAt: anAssociation) notNil	ifTrue:	[		^ (first perform: self operation)	]	ifFalse:	[		^ nil	]! !!ExpressionUnary methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:42'!printSqueak	"Answer a string representation of myself"	"^ '(', self term printSqueak, ') ', self operation printString"	^ self term printSqueak, ' ', self operation printString! !!ExpressionUnary methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:49'!printString	"Answer a string representation of myself"	^ self operationString, '(', self term printString, ')'	"^ self operationString, ' ', self term printString, ''"! !!ExpressionUnary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:19'!reduceConstantSubexpressions	"collapse any constant subexpressions"	self isConstantExpression	ifTrue:	[		"Reduce to a single constant"		^ self class newConstant: self evaluate	]	ifFalse:	[		^ self	]! !!ExpressionUnary methodsFor: 'private-initialization' stamp: 'jmi 5/20/2000 21:38'!term: anExpression	"Learn my term"	^ self term: anExpression simplify: true.! !!ExpressionUnary methodsFor: 'private-initialization' stamp: 'jmi 5/20/2000 14:22'!term: anExpression simplify: aBoolean	"Learn my term"	term _ anExpression.	aBoolean	ifTrue:	[		^ self simplify.	].	^ self.! !!ExpressionUnary methodsFor: 'testing' stamp: 'jmi 7/1/2000 11:21'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	^	(self operation == arg operation)	and:		[ self term = arg term ].! !!ExpressionUnary methodsFor: 'testing' stamp: 'jmi 4/23/2000 18:27'!isConstantExpression	"Answer true if I only contain constants,	 answer false if I contain variables"	^ self term isConstantExpression! !!ExpressionCos methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:25'!operation	"Answer the symbol for the operation I represent"	^ #cos! !!ExpressionCos methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:11'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self term protectedDerivative: aSymbol) * (self term sin negated)! !!ExpressionLn methodsFor: 'operation' stamp: 'jmi 4/23/2000 18:28'!operation	"Answer the symbol for the operation I represent"	^ #ln! !!ExpressionLn methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:13'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self term protectedDerivative: aSymbol) / (self term)! !!ExpressionSin methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:22'!operation	"Answer the symbol for the operation I represent"	^ #sin! !!ExpressionSin methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:14'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self term protectedDerivative: aSymbol) * (self term cos)! !!ExpressionTan methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:32'!operation	"Answer the symbol for the operation I represent"	^ #tan! !!ExpressionTan methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:14'!protectedDerivative: aSymbol	"Answer my derivative"	^ (self term protectedDerivative: aSymbol) / (self term cos squared)! !!ExpressionValue methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:22'!value	"Answer my value"	^ value! !!ExpressionValue methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:38'!printSqueak	"Answer a string representation of myself"	^ self printString! !!ExpressionValue methodsFor: 'printing' stamp: 'jmi 4/26/2000 13:00'!printString	"Answer a string representation of myself"	^ self value asString! !!ExpressionValue methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 22:30'!value: aValue	"Learn my value"	"aValue isNumber	ifTrue:	["		"Floating point math is 1000 times faster than Fractional"		value _ aValue "	]	ifFalse:	[		value _ aValue	]"! !!ExpressionValue methodsFor: 'operation' stamp: 'jmi 5/15/2000 22:24'!operation	"Values don't HAVE an operation, but need something distinct to tell them apart from the other expressions"	^ nil! !!ExpressionValue methodsFor: 'operation' stamp: 'jmi 5/18/2000 10:37'!operationString	"Values don't HAVE an operation, but need something distinct to tell them apart from the other expressions"	^ self shouldNotImplement! !!ExpressionValue methodsFor: 'testing' stamp: 'jmi 7/1/2000 11:20'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	^	(self operation == arg operation)	and:		[ self value = arg value ].! !!ExpressionConstant methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:25'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ aSet! !!ExpressionConstant methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:13'!at: aDictionaryOrNumber	"I am a constant.  I don't care what you pass me.  I always answer my value."	^ self value.! !!ExpressionConstant methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:42'!partialAt: anAssociation	"I am a constant.  I don't care what you pass me.  I always answer my value."	^ self class newConstant: self value.! !!ExpressionConstant methodsFor: 'printing' stamp: 'jmi 5/14/2000 22:22'!printString	"Answer a string representation of myself"	self value < 0	ifTrue:	[		"This is so I don't have to add a negation operator"			"The parser doesn't know the difference between			binary subtraction and unary minus.  It assumes any			operation right after an open parenthesis is unary"		^ '(', self value asString, ')'	]	ifFalse:	[		^ self value asString	]! !!ExpressionConstant methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:11'!protectedDerivative: aSymbol	"Answer my derivative (always zero)"	^ self class newConstant: 0! !!ExpressionConstant methodsFor: 'testing' stamp: 'jmi 4/25/2000 13:10'!isConstantExpression	"Answer true since I'm a constant"	^ true! !!ExpressionVariable methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:35'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	aSet add: self value.	^ aSet! !!ExpressionVariable methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:15'!at: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	(aDictionaryOrNumber isNumber or: [ aDictionaryOrNumber == nil])	ifTrue:	[		^ aDictionaryOrNumber.	]	ifFalse:	[					"nil return value for an undefined variable"		^ (aDictionaryOrNumber at: self value ifAbsent: [ nil ])	].! !!ExpressionVariable methodsFor: 'evaluation' stamp: 'jmi 5/20/2000 14:42'!partialAt: anAssociation	"Evaluate my expression using the value association."	anAssociation key == self value	ifTrue:	[		^ self class newConstant: anAssociation value.	]	ifFalse:	[		^ self class newVariable: self value.	].! !!ExpressionVariable methodsFor: 'symbolic' stamp: 'jmi 5/18/2000 11:15'!protectedDerivative: aSymbol	"Answer my derivative (always one or zero)"	(self value = aSymbol)	ifTrue:	[		^ self class newConstant: 1.	]	ifFalse:	[		^ self class newConstant: 0.	]! !!ExpressionVariable methodsFor: 'testing' stamp: 'jmi 4/25/2000 13:10'!isConstantExpression	"Answer true if I'm a constant"	^ false! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/18/2000 19:14'!extent: aPoint	"Learn my extent"	"This has become my 'initialize' method"	extent _ aPoint.	translationFactor _ extent / 2.0.		"Create a new display medium"	form _ (Form extent: extent) fillWhite.		"Make a new line drawer"	lineDrawer _ BitBlt 		destForm: form		sourceForm: (Form extent: 1@1) fillBlack		fillColor: Color black		combinationRule: Form over		destOrigin: 0@0		"If I set the origin here, do I not have to add it later?!!"		sourceOrigin: 0 @ 0		extent: extent		clipRect: (1@1 extent: extent).! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/16/2000 09:00'!function	"Answer my function"	^ function! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/18/2000 19:11'!position	"Answer my position"	^ position.! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/18/2000 19:11'!position: aPoint	"Learn my position"	position _ aPoint.! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/16/2000 12:02'!turn: zAngle tilt: xAngle twist: yAngle		"Build the rotation matrix"	pointRotation _ PointRotation turn: zAngle tilt: xAngle twist: yAngle.! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/17/2000 16:13'!convertTo2d: anArrayOf3Numbers	"Answer screen cordinates for the 3d point		Add depth perception and invert the y-axiz (screen cordinates are backwards from cartesian)"	| depthPerceptionFactor |	depthPerceptionFactor _ pointOfView / (pointOfView - (anArrayOf3Numbers at: 3)).	^ ((anArrayOf3Numbers at: 1) * depthPerceptionFactor) @		((anArrayOf3Numbers at: 2) * depthPerceptionFactor negated).! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 7/1/2000 13:38'!displayForm	"Display the form"	form displayAt: position.		"Allow the screen to refresh if in Morphic"	World ~~ nil	ifTrue:	[	World doOneCycle.	].! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/16/2000 10:02'!graph	"Graph it!!"	function evaluateOn: self.		"Hack to display the last form"	self displayForm.! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/17/2000 17:37'!lineFrom: firstPoint to: secondPoint	"Draw a line between the two points"	| begin end |		"If either point is invalid, return"	firstPoint ifNil: [ ^ self ].	secondPoint ifNil: [ ^ self ].	"Check for change in time"	lastTime ~= (firstPoint at: 4)	ifTrue:	[			"Don't display the blank white form"		lastTime ~~ nil ifTrue: [ self displayForm.].		lastTime _ firstPoint at: 4.		form fillWhite.	"This takes a little longer than just creating a new form,							but doesn't cause as much garbage collection"	].		"Rotate each point, so the graph is more visible"	begin _ pointRotation rotatePoint: firstPoint.	end _ pointRotation rotatePoint: secondPoint.		"Convert each point to screen cordinates"	begin _ self convertTo2d: begin.	end _ self convertTo2d: end.		"Scale and translate the coordinates"	begin _ begin * scaleFactor + translationFactor.	end _ end * scaleFactor + translationFactor.		"Draw the line!!"	lineDrawer drawFrom: begin to: end withFirstPoint: true.! !!FunctionGraph methodsFor: 'initialization' stamp: 'jmi 5/16/2000 09:01'!function: aFunction	"Learn my function"	function _ aFunction.		"Determine how much the function needs to be resized to fit on the form"	scaleFactor _ ((extent x min: extent y) / function maxPlanarExtent) asFloat.		"This is so it doesn't have to be converted to a point later			(a scalar is first converted to a point when doing arithmetic between the two)"	scaleFactor _ scaleFactor @ scaleFactor.! !!FunctionGraph methodsFor: 'initialization' stamp: 'jmi 5/20/2000 15:01'!initialize	"Set defaults"	pointOfView _ 20.0.	lastTime _ nil.	self position: 0@0.	self extent: 640@480.	self	turn:	(Float pi / 4)		tilt:		(Float pi / 4)		twist:	0.! !!FunctionGraph class methodsFor: 'big example' stamp: 'jmi 9/13/2000 10:43'!bigExample"Be prepared to wait a while if you run this method""	FunctionGraph bigExample"	| delay |Expression initialize.  "just to be sure it's initialized"	delay _ Delay forSeconds: 2.	FunctionGraph example.delay wait.	FunctionGraph example2d1.delay wait.	FunctionGraph example2d1Rotate.delay wait.	FunctionGraph example2d1RotateTilt.	FunctionGraph example2d1RotateTurn.	FunctionGraph example2d1RotateTwist.	FunctionGraph example2d1.delay wait.	FunctionGraph example2d1TransformZtoTimeRotateTwist.	FunctionGraph example2d2.delay wait.	FunctionGraph example2d2Rotate.delay wait.	FunctionGraph example3d.delay wait.	FunctionGraph example3dPolar.delay wait.	FunctionGraph example4d.	FunctionGraph example4d2.	FunctionGraph example4d2Twist.	FunctionGraph example4d3.	FunctionGraph example4d3Turn.	FunctionGraph example4dPolar.	FunctionGraph example4dPolar2.	FunctionGraph example4dPolar3.	FunctionGraph example4dPolar4.	FunctionGraph example4dPolarCylindrical.	FunctionGraph example4dPolarCylindrical2.	FunctionGraph example4dPolarCylindrical2Tilt.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/14/2000 17:24'!example	"Example of what you can do with a graph"	self testFunction: (FunctionNd forExpression3d: '0' asExpression).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:12'!example2d1	"Example of what you can do with a graph"	| function |	function _ FunctionNd forExpression2d: '(sin(x))' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:13'!example2d1Rotate	"Example of what you can do with a graph"	| function |	function _ FunctionTransformRotate					forFunction: (FunctionNd forExpression2d: '(sin(x))' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:14'!example2d1RotateTilt	"Example of what you can do with a graph""	FunctionGraph example2d1RotateTilt"	| function |	function _ FunctionTransformTilt forFunction:				 (FunctionTransformRotate forFunction:					(FunctionTransformYtoTime forFunction:						(FunctionNd forExpression3d: '(sin(x))' asExpression))).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 22:16'!example2d1RotateTurn	"Example of what you can do with a graph""	FunctionGraph example2d1RotateTurn"	| function |	function _ FunctionTransformTurn forFunction:				 (FunctionTransformRotate forFunction:					(FunctionTransformYtoTime forFunction:						(FunctionNd forExpression3d: '(sin(x))' asExpression))).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/18/2000 10:04'!example2d1RotateTwist	"Example of what you can do with a graph""	FunctionGraph example2d1RotateTwist"	| function |	function _ FunctionTransformTwist forFunction:				 (FunctionTransformRotate forFunction:					(FunctionTransformYtoTime forFunction:						(FunctionNd forExpression3d: '(sin(x))' asExpression))).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/18/2000 10:03'!example2d1TransformZtoTimeRotateTwist	"Example of what you can do with a graph""	FunctionGraph example2d1TransformZtoTimeRotateTwist"	FunctionGraph testFunction:			(FunctionTransformTwist forFunction:				 (FunctionTransformRotate forFunction:					(FunctionTransformZtoTime forFunction:						(FunctionNd forExpression3d: '(sin(x))' asExpression)))).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:36'!example2d2	"Example of what you can do with a graph"	| function |	function _ FunctionNd forExpression2d: '(25-x^2)^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:11'!example2d2Rotate	"Example of what you can do with a graph"	| function |	function _ FunctionTransformRotate					forFunction: (FunctionNd forExpression2d: '(25-x^2)^0.5' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 18:30'!example3d	"Example of what you can do with a graph""	self test3d: '(sin(x)+sin(y))'."	| graph function expression |	expression _ ('(sin(x)+sin(y))' asExpression).	function _ FunctionNd forExpression3d: expression.		"This is the setting I used when testing Lex's code"	function		extent: 10		resolution: 20.	graph _ self forFunction: function.	graph graph! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 12:55'!example3dPolar	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression3d: ('3' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:30'!example3dTimeTest	"Example of what you can do with a graph"	^ MessageTally time: [100 timesRepeat: [	self example3d ]]! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:34'!example4d	"Example of what you can do with a graph"		"Hypersphere!!"	self testFunction: (FunctionNd forExpression4d: '(30-x^2-y^2-t^2)^0.5').! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:34'!example4d2	"Example of what you can do with a graph"	self testFunction: (FunctionNd forExpression4d: '(sin(x)+sin(t+y))').! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:09'!example4d2Twist	"Example of what you can do with a graph"	self testFunction: (FunctionTransformTwist forFunction: (FunctionNd forExpression4d: '(sin(x)+sin(t+y))')).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:34'!example4d3	"Example of what you can do with a graph"	self testFunction: (FunctionNd forExpression4d: '(sin(t+x)+sin(t*y))').! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:09'!example4d3Turn	"Example of what you can do with a graph"	self testFunction: (FunctionTransformTurn forFunction: (FunctionNd forExpression4d: '(sin(t+x)+sin(t*y))')).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 13:39'!example4dPolar	"Example of what you can do with a graph"	| function |		"Hypersphere!!"	function _ FunctionNdPolar forExpression4d: '3' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:42'!example4dPolar2	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression4d: 'x' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:43'!example4dPolar3	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression4d: '(10*sin(2*t*x)*sin(2*t*y))^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:45'!example4dPolar4	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression4d: '(10*sin(t*x)*sin(t*y))^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 13:44'!example4dPolarCylindrical	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolarCylindrical forExpression4d: '(10*sin(t*x)*sin(t*y))^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 16:32'!example4dPolarCylindrical2	"Example of what you can do with a graph""		FunctionGraph example4dPolarCylindrical2"	| function |	function _ FunctionNdPolarCylindrical forExpression4d: '3*(sin(y)-sin(t))' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/17/2000 17:10'!example4dPolarCylindrical2Tilt	"Example of what you can do with a graph""		FunctionGraph example4dPolarCylindrical2Tilt"	| function |	function _ FunctionTransformTilt forFunction: (FunctionNdPolarCylindrical forExpression4d: '3*(sin(y)-sin(t))' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/14/2000 19:11'!testFunction: aFunction	"Example of what you can do with a graph"	| graph |	graph _ self forFunction: aFunction.	graph graph! !!FunctionGraph class methodsFor: 'instance creation' stamp: 'jmi 5/18/2000 19:10'!forFunction: aFunction	^ super new initialize		function: aFunction.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/20/2000 14:07'!evaluate: partialExpression at: currentDimension with: thePoint on: aGraph		"Skip the dependent variable dimension"	currentDimension = 2	ifTrue:	[	^ self evaluateX: partialExpression with: thePoint on: aGraph. ].		"BAD BAD HORRIBLE CODE!!  Must make a better way."		"lastXRow needs to be initialized before the y loop"	currentDimension = 3	ifTrue:	[	lastXRow atAllPut: nil	].		"Loop across the currentDimension's axiz"	(nInterval at: currentDimension)	do:	[:value |			"getPointAt: needs all the values to make a copy (or convert to polar, etc...)"		thePoint at: currentDimension put: value.			"Partially evaluate the expression so it's smaller (evaluates faster) as the recursion continues"		self			evaluate: (partialExpression partialAt: ((nVariable at: currentDimension) -> value))			at:		currentDimension - 1			with:	thePoint			on:		aGraph.	].! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/18/2000 14:11'!evaluateOn: aGraph	"Loop through each independent axis and tell aGraph what lines to draw"	| nValues |		"Provide at least 4 slots for values, since FunctionGraph expects that many"	nValues _ Array new: (4 max: self dimensions).	nValues atAllPut: 0.	^ self		evaluate: expression		at: self dimensions		with: nValues		on: aGraph.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/20/2000 14:07'!evaluateX: partialExpression with: thePoint on: aGraph	"Loop through the innermost axis (the x-axis)"	| lastPoint currentPoint position |		"Initializations"	position _ 1.	lastPoint _ nil.		"The innermost loop!!"	(nInterval at: 1) do:	[:value |			"update the 'x' value"		thePoint at: 1 put: value.					"evaluateAt: is faster than partialEvaluationAt: so just use that for the innermost loop"		currentPoint _ self							getPointAt: (partialExpression at: value)							with: thePoint."Is it faster to nil check here and never even call lineFrom:to:?"			"Graph the 2 lines from the currentPoint"		aGraph lineFrom: lastPoint to: currentPoint.		aGraph lineFrom: (lastXRow at: position) to: currentPoint.			"increment counters/update temporary variables"		lastXRow at: position put: currentPoint.		position _ position + 1.		lastPoint _ currentPoint.	].! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/18/2000 13:16'!getPointAt: aNumber with: thePoint	aNumber == nil	ifTrue: [ ^ nil ].		"add the dependent variable value"	thePoint at: 2 put: aNumber.	^ self transform: thePoint.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/18/2000 13:13'!transform2: thePoint	"default action is to return a copy"	| newPoint |	"If you don't return a copy, a bunch of points get graphed instead of a wireframe (try it and see)"	"I really need to just store the values in the correct order"		"It might be a little slower, but will now handle any dimension"	newPoint _ Array new: thePoint size.	newPoint at: 1 put: (thePoint at: 1).	newPoint at: 2 put: (thePoint at: 3).	newPoint at: 3 put: (thePoint at: 2).	4 to: newPoint size do:	[:i |		newPoint at: i put: (thePoint at: i).	].	^ newPoint.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/18/2000 14:07'!transform: thePoint	"default action is to return a copy"	| newPoint |	"If you don't return a copy, a bunch of points get graphed instead of a wireframe (try it and see)""^ {	thePoint at: 1.	thePoint at: 3.	thePoint at: 2.	thePoint at: 4	}"		"It might be a little slower, but will now handle any dimension"	newPoint _ thePoint copy.		"Swap the y and z values to their correct locations"	newPoint at: 2 put: (thePoint at: 3).	newPoint at: 3 put: (thePoint at: 2).	^ newPoint.! !!FunctionNd methodsFor: 'info for graph' stamp: 'jmi 5/16/2000 17:02'!maxPlanarExtent	"Answer the maximum (diagonal, or whatever) extent possible in the xy plane"	| nExtent |		"Calculate the extents for each dimension"	nExtent _ nMax - nMin.	self dimensions < 3	ifTrue:	[		^ (nExtent at: 1) abs	]	ifFalse:	[			"Diagonal made between the width and depth"		^ ((nExtent at: 1) squared + (nExtent at: 3) squared) sqrt.	].! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/14/2000 22:56'!dimensions	"Answer my number of dimensions"	^ dimensions! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/18/2000 13:18'!expression: anExpression	"Learn my expression"	expression _ anExpression asExpression."	self changed."! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/18/2000 13:19'!extent: aNumber resolution: aPositiveInteger	"Learn my extent and resolution"	self extent: aNumber.	self resolution: aPositiveInteger.		"update the nStep variable (or nInterval if I try that again)"	self updateInterval.		"create the temporary holder for the innermost loop"	lastXRow _ Array new: resolution + 1 withAll: nil.! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/20/2000 14:59'!initialize: variables	"nDimensional initialization (currently only known to support 3d/4d)		it may work fine for other dimensions, but I haven't tested those yet"		"A function of 1 variable accounts for 2 dimensions.					of 2 variables accounts for 3 dimensions, etc..."	dimensions _ variables size + 1.		"Set default extent/resolution"	self		extent: 4.0 * Float pi		resolution: 30.		"Create the array of variable names"	nVariable _ Array new: self dimensions.	nVariable at: 1 put: (variables at: 1).	nVariable at: 2 put: #dependentVariable.		"Never actually used.  Just a placeholder."	2 to: variables size do:	[:index |		nVariable at: index + 1 put: (variables at: index).	].! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/14/2000 23:29'!resolution	"Answer my resolution"	^ resolution! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/16/2000 13:49'!updateInterval	"Set the loop intervals"	| nStep |	nStep _ ((nMax - nMin) / resolution) asArray.	nInterval _ Array new: self dimensions.	1 to: self dimensions do:	[:dimension |		nInterval at: dimension put: (					(nMin at: dimension) to:					(nMax at: dimension) + 0.01 by:					(nStep at: dimension)					).	].	! !!FunctionNd methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 23:30'!extent: aNumber	"Set the extent for the n-dimensional cube"	nMax _ Array new: self dimensions.	nMax atAllPut: (aNumber / 2.0) asFloat.	nMin _ nMax negated.! !!FunctionNd methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 23:30'!resolution: aPositiveInteger	"Learn my resolution"	resolution _ aPositiveInteger.! !!FunctionNd methodsFor: 'for prototype interface-accessors/modifiers' stamp: 'jmi 5/14/2000 18:54'!expressionString	"Answer my expression string"	^ expression printString! !!FunctionNd methodsFor: 'for prototype interface-accessors/modifiers' stamp: 'jmi 5/14/2000 19:42'!expressionString: aStringOrText	"Learn my expression"	| tmpExpression ok |	ok _ true.	[		tmpExpression _ aStringOrText asString asExpression.	]	ifError: [:err :msg | ok _ false ].	tmpExpression ifNil: [ ok _ false ].	ok ifTrue:	[		self expression: tmpExpression.	].	^ ok.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/17/2000 09:08'!forExpression2d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 16:04'!forExpression3d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x. #y }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 16:14'!forExpression4d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x. #y. #t }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 15:57'!forExpression: anExpression ofVariables: anArray	"Answer a Function for anExpression"	"The second dimension is always the dependent variable, and thus shouldn't be listed in anArray.	For example, say you want a 2d Function (y in terms of x).  You would pass { #x }.	If you wanted a 3d function, say z in terms of x and y, you simply pass { #x. #y }.	If you want a 4d function, say z in terms of x y and t, you simply pass { #x. #y. #t }.	Order DOES matter, meaning the first variable always corresponds to the x-axis,		second to y-axis, and third to the time axis"	^ super new		initialize: anArray;		expression: anExpression.! !!FunctionNdPolar methodsFor: 'calculation' stamp: 'jmi 5/20/2000 15:19'!transform: thePoint	"convert nValue to polar (spherical) form"	| theta phi r t newPoint |	theta _ thePoint at: 1.	r _ thePoint at: 2.	phi _ thePoint at: 3.	t _ thePoint at: 4."		^ {			r * t cos * phi sin * theta cos.			r * t cos * phi sin * theta sin.			r * t cos * phi cos.			t		}."		"Might be a little slower, but handles any dimension"	newPoint _ thePoint copy.	newPoint at: 1 put: r * t cos * phi sin * theta cos.	newPoint at: 2 put: r * t cos * phi sin * theta sin.	newPoint at: 3 put: r * t cos * phi cos.	^ newPoint.! !!FunctionNdPolar methodsFor: 'initialization' stamp: 'jmi 5/14/2000 16:01'!extent: aNumber	| tmpArray |	"Ignore the passed value.  Set the polar values instead."	nMax _ Array new: self dimensions.	nMax atAllPut: Float halfPi.	nMin _ nMax negated.	tmpArray _ {		2.0 * Float pi.		0. "Dependent variable placeholder"		Float pi	}.	1 to:  (3 min: self dimensions) do:	[:dimension |		nMin at: dimension put: 0.0.		nMax at: dimension put: (tmpArray at: dimension).	].! !!FunctionNdPolarCylindrical methodsFor: 'calculation' stamp: 'jmi 5/17/2000 17:49'!transform: thePoint	"convert nValue to polar (cylindrical) form"	| theta phi r newPoint |	theta _ thePoint at: 1.	r _ thePoint at: 2.	phi _ thePoint at: 3."	t _ thePoint at: 4.""		^ {			r * phi sin * theta cos.			r * phi sin * theta sin.			r * phi cos.			t		}."		"Might be a little slower, but handles any dimension"	newPoint _ thePoint copy.	newPoint at: 1 put: r * phi sin * theta cos.	newPoint at: 2 put: r * phi sin * theta sin.	newPoint at: 3 put: r * phi cos.	^ newPoint! !!FunctionNdPolarCylindrical methodsFor: 'initialization' stamp: 'jmi 5/14/2000 23:33'!extent: aNumber	| tmpArray |	"Ignore the passed value.  Set the polar values instead."	nMax _ Array new: self dimensions.	nMax atAllPut: Float pi.	nMin _ Array new: self dimensions.	nMin atAllPut: 0.	tmpArray _ {		2.0 * Float pi.		0. "Dependent variable placeholder"		Float pi	}.	1 to:  (3 min: self dimensions) do:	[:dimension |		nMax at: dimension put: (tmpArray at: dimension).	].! !!FunctionTransform methodsFor: 'function' stamp: 'jmi 5/17/2000 11:58'!dimensions	"Answer the number of dimensions I graph, after I apply my 'transformation'"	^ function dimensions! !!FunctionTransform methodsFor: 'function' stamp: 'jmi 5/16/2000 14:08'!evaluateOn: aGraph	"Loop through each independent axis and tell aGraph what lines to draw"	graph _ aGraph.	^ function evaluateOn: self! !!FunctionTransform methodsFor: 'function' stamp: 'jmi 5/16/2000 13:59'!maxPlanarExtent	^ function maxPlanarExtent.! !!FunctionTransform methodsFor: 'graph' stamp: 'jmi 5/16/2000 16:39'!function: aFunction	function _ aFunction.! !!FunctionTransform methodsFor: 'graph' stamp: 'jmi 5/17/2000 13:12'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	^ graph		lineFrom:	(self transform: firstPoint)		to:			(self transform: secondPoint).! !!FunctionTransform methodsFor: 'graph' stamp: 'jmi 5/17/2000 13:10'!transform: thePoint	"Default action is to rotate the point by the specified value"	^ pointRotation rotatePoint: thePoint.! !!FunctionTransform methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:33'!initialize	pointRotation _ PointRotation identity.! !!FunctionTransform class methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 12:38'!forFunction: aFunction	"This should be the ONLY instance creation method for FunctionTransform"	^ super new initialize function: aFunction.! !!FunctionTransformRotate methodsFor: 'graph' stamp: 'jmi 5/17/2000 11:58'!dimensions	"Answer the number of dimensions I graph, after I apply my 'transformation'"	^ 3 max: function dimensions! !!FunctionTransformRotate methodsFor: 'graph' stamp: 'jmi 5/17/2000 13:13'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	pointRotators == nil	ifTrue:	[		pointRotators _ Array new: ((Float pi * 2.0) / (Float pi / 8.0)) rounded + 1.		1 to: pointRotators size do:		[:index |			pointRotators at: index put: (PointRotation turn: 0.0 tilt: (Float pi / 8.0) * index twist: 0.0).		].	].	1 to: pointRotators size - 1 do:	[:i |		graph			lineFrom:	((pointRotators at: i + 1) rotatePoint: secondPoint)			to:			((pointRotators at: i) rotatePoint: secondPoint).		graph			lineFrom:	((pointRotators at: i) rotatePoint: firstPoint)			to:			((pointRotators at: i) rotatePoint: secondPoint).	].! !!FunctionTransformTilt methodsFor: 'graph' stamp: 'jmi 5/18/2000 00:16'!transform: thePoint	initialTime == nil	ifTrue: [ initialTime _ (thePoint at: 4 ) / 2.0	].		"Recalculation slows it down a LOT.		the pointRotation cache speeds it back up"	lastTime ~= (thePoint at: 4)	ifTrue:	[		lastTime _ thePoint at: 4.		pointRotation turn: 0.0 tilt: lastTime - initialTime twist: 0.0.	].	^ pointRotation rotatePoint: thePoint.! !!FunctionTransformTurn methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 16:55'!transform: thePoint	initialTime == nil	ifTrue: [ initialTime _ (thePoint at: 4 ) / 2.0	].		"Recalculation slows it down a LOT.		the pointRotation cache speeds it back up"	lastTime ~= (thePoint at: 4)	ifTrue:	[		lastTime _ thePoint at: 4.		pointRotation turn: lastTime / 2.0 - initialTime tilt: 0.0 twist: 0.0.	].	^ pointRotation rotatePoint: thePoint.! !!FunctionTransformTwist methodsFor: 'graph' stamp: 'jmi 5/17/2000 12:00'!dimensions	"Answer the number of dimensions I graph, after I apply my 'transformation'	Only a function with a time dimension can twist over a period of time, so it's at least 4.	Actually, PointRotation ignores dimensions higher than 4... so it should only return 4"	^ 4 max: function dimensions! !!FunctionTransformTwist methodsFor: 'graph' stamp: 'jmi 5/17/2000 16:26'!transform: thePoint	initialTime == nil	ifTrue: [ initialTime _ (thePoint at: 4 ) / 2.0	].		"Recalculation slows it down a LOT.		the pointRotation cache speeds it back up"	lastTime ~= (thePoint at: 4)	ifTrue:	[		lastTime _ thePoint at: 4.		pointRotation turn: 0.0 tilt: 0.0 twist: lastTime / 2.0 - initialTime.	].	^ pointRotation rotatePoint: thePoint.! !!FunctionTransformXtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 22:50'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	(firstPoint at: 1) ~= (secondPoint at: 1)	ifTrue:	[		^ self.	].	graph		lineFrom: (self transform: firstPoint)		to: (self transform: secondPoint).! !!FunctionTransformXtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 22:51'!transform: thePoint		^ {			0.0.			thePoint at: 2.			thePoint at: 3.			thePoint at: 1		}! !!FunctionTransformYtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 16:52'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	(firstPoint at: 2) ~= (secondPoint at: 2)	ifTrue:	[		^ self.	].	graph		lineFrom: (self transform: firstPoint)		to: (self transform: secondPoint).! !!FunctionTransformYtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 16:51'!transform: thePoint		^ {			thePoint at: 1.			0.0.			thePoint at: 3.			thePoint at: 2		}! !!FunctionTransformZtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 14:21'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	(firstPoint at: 3) ~= (secondPoint at: 3)	ifTrue:	[		^ self.	].	graph		lineFrom: (self transform: firstPoint)		to: (self transform: secondPoint).! !!FunctionTransformZtoTime methodsFor: 'as yet unclassified' stamp: 'jmi 5/17/2000 14:22'!transform: thePoint		^ {			thePoint at: 1.			thePoint at: 2.			0.0.			thePoint at: 3		}! !!Number methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 19:22'!negativeRaisedToNonIntegerPower: aNumber	"I'm getting really annoyed with the pink boxes!!"	"this assumes the message is sent to a negative number!!"	"		IMAGINARY: negative raisedTo: (odd/even)		NEGATIVE:	negative raisedTo: (odd/odd)		POSITIVE:	negative raisedTo: (even/odd)	"	| returnValue exponent |	exponent _ aNumber asFraction.	exponent denominator even	ifTrue:	[		"self error: self printString, ' raised to non integer power, and result is complex'."		^ nil "0.0" "Just testing something."	]	ifFalse:	[		returnValue _ self negated raisedTo: aNumber.		exponent numerator even		ifTrue:		[			^ returnValue		]		ifFalse:		[			^ returnValue negated		].	].! !!Number methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 18:19'!raisedTo: aNumber 	"Answer the receiver raised to aNumber."	aNumber isInteger ifTrue:		["Do the special case of integer power"		^ self raisedToInteger: aNumber].	self < 0 ifTrue:		[ "self error: self printString, ' raised to a non-integer power'"			^ self negativeRaisedToNonIntegerPower: aNumber		 ].	aNumber = 0 ifTrue: [^ 1].		"Special case of exponent=0"	(self = 0) | (aNumber = 1) ifTrue:		[^ self].						"Special case of exponent=1"	^ (aNumber * self ln) exp		"Otherwise use logarithms"! !!Float methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 17:57'!raisedTo: aNumber	"Answer the receiver raised to aNumber."	aNumber isInteger ifTrue:		["Do the special case of integer power"		^ self raisedToInteger: aNumber].	self < 0.0 ifTrue:		[ "self error: self printString, ' raised to a non-integer power'"			^ self negativeRaisedToNonIntegerPower: aNumber ].	0.0 = aNumber ifTrue: [^ 1.0].				"special case for exponent = 0.0"	(self= 0.0) | (aNumber = 1.0) ifTrue: [^ self].	"special case for self = 1.0"	^ (self ln * aNumber asFloat) exp			"otherwise use logarithms"! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:17'!resetToIdentity	"Reset to the identity matrix"	a _ 1.	b _ 0.	c _ 0.	d _ 0.	e _ 1.	f _ 0.	g _ 0.	h _ 0.	i _ 1.! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:16'!setZRotation: angle	"Set the matrix used to rotate angle radians around the z-axiz"	angle = 0.0 ifTrue: [ ^ self resetToIdentity ].	a _ angle cos.	b _ angle sin negated.	c _ 0.	d _ angle sin.	e _ angle cos.	f _ 0.	g _ 0.	h _ 0.	i _ 1.! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:54'!turn: zAngle tilt: xAngle twist: yAngle	"Build the rotation matrix"	"self zRotation: zAngle."		"Just plain setting the zRotation matrix is faster than multiplying by the identity"	self setZRotation: zAngle.	self xRotation: xAngle.	self yRotation: yAngle.! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:54'!xRotation: angle	| a12 a13 a22 a23 a32 a33 b22 b23 b32 b33 |	"Answer the matrix used to rotate angle radians around the x-axiz"	"If no rotation is needed, don't DO anything"	angle = 0.0 ifTrue: [ ^ self ].	a12 _ b.	a13 _ c.	a22 _ e.	a23 _ f.	a32 _ h.	a33 _ i."	{		1. 0. 0.		0. angle cos. angle sin negated.		0. angle sin. angle cos	}""	b11 _ 1.""	b12 _ 0.""	b13 _ 0.""	b21 _ 0."	b22 _ angle cos.	b23 _ angle sin negated."	b31 _ 0."	b32 _ angle sin.	b33 _ angle cos.	b _ (a12 * b22) + (a13 * b32).	c _ 	(a12 * b23) + (a13 * b33).	e _ 	(a22 * b22) + (a23 * b32).	f _ 	(a22 * b23) + (a23 * b33).	h _ (a32 * b22) + (a33 * b32).	i _ (a32 * b23) + (a33 * b33).! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:54'!yRotation: angle	| a11 a13 a21 a23 a31 a33 b11 b13 b31 b33 |	"Answer the matrix used to rotate angle radians around the y-axiz"	"If no rotation is needed, don't DO anything"	angle = 0.0 ifTrue: [ ^ self ].	a11 _ a.	a13 _ c.	a21 _ d.	a23 _ f.	a31 _ g.	a33 _ i."	{		angle cos. 0. angle sin.		0. 1. 0.		angle sin negated. 0. angle cos	}."	b11 _ angle cos."	b12 _ 0."	b13 _ angle sin."	b21 _ 0.""	b22 _ 1.""	b23 _ 0."	b31 _ angle sin negated."	b32 _ 0."	b33 _ angle cos.	a _ (a11 * b11) + (a13 * b31).	c _ 	(a11 * b13) + (a13 * b33).	d _ 	(a21 * b11) + (a23 * b31).	f _ 	(a21 * b13) + (a23 * b33).	g _ (a31 * b11) + (a33 * b31).	i _ (a31 * b13) + (a33 * b33).! !!PointRotation methodsFor: 'initialization' stamp: 'jmi 5/17/2000 12:54'!zRotation: angle	| a11 a12 a21 a22 a31 a32 b11 b12 b21 b22 |	"Answer the matrix used to rotate angle radians around the z-axiz"	"If no rotation is needed, don't DO anything"	angle = 0.0 ifTrue: [ ^ self ].	a11 _ a.	a12 _ b.	a21 _ d.	a22 _ e.	a31 _ g.	a32 _ h."	{		angle cos. angle sin negated. 0.		angle sin. angle cos. 0.		0. 0. 1	}."	b11 _ angle cos.	b12 _ angle sin negated."	b13 _ 0."	b21 _ angle sin.	b22 _ angle cos."	b23 _ 0.""	b31 _ 0.""	b32 _ 0.""	b33 _ 1."	a _ (a11 * b11) + (a12 * b21).	b _ (a11 * b12) + (a12 * b22).	d _ 	(a21 * b11) + (a22 * b21).	e _ 	(a21 * b12) + (a22 * b22).	g _ (a31 * b11) + (a32 * b21).	h _ (a31 * b12) + (a32 * b22).! !!PointRotation methodsFor: 'rotation' stamp: 'jmi 5/18/2000 19:17'!rotatePoint: array	| thePoint |	"Answer the product of rotation matrix by point array"	"It's probably backwards, so be sure to check it."		"Answer the rotated point""	^ {		(a * (array at: 1)) + (d * (array at: 2)) + (g * (array at: 3)).		(b * (array at: 1)) + (e * (array at: 2)) + (h * (array at: 3)).		(c * (array at: 1)) + (f * (array at: 2)) + (i * (array at: 3)).		array at: 4	}."	"It's slower, but handles ANY number of dimensions"	thePoint _ array copy.	thePoint at: 1 put:	(a * (array at: 1)) + (d * (array at: 2)) + (g * (array at: 3)).	thePoint at: 2 put:	(b * (array at: 1)) + (e * (array at: 2)) + (h * (array at: 3)).	thePoint at: 3 put:	(c * (array at: 1)) + (f * (array at: 2)) + (i * (array at: 3)).	^ thePoint.! !!PointRotation class methodsFor: 'instance creation' stamp: 'jmi 5/17/2000 12:18'!identity	"Answer the identity matrix"	^ super new resetToIdentity! !!PointRotation class methodsFor: 'instance creation' stamp: 'jmi 5/17/2000 12:19'!turn: zAngle tilt: xAngle twist: yAngle	^ self identity turn: zAngle tilt: xAngle twist: yAngle.! !!String methodsFor: 'converting' stamp: 'jmi 4/25/2000 13:03'!asExpression	"Answer an Expression whose text string is the receiver."	^ Expression newFromString: self asString! !Expression initialize!